import java.util.ArrayList;
import java.util.List;

class Todo {
    private String what;
    private boolean done;

    Todo(String what, boolean done) {
        this.what = what;
        this.done = done;
    }

    String getWhat() { return what; }
    void markDone() { done = true; }

    @Override
    public String toString() {
        return (done ? "[x] " : "[ ] ") + what;
    }
}

public class Main {
    public static void main(String[] args) {
        List<Todo> zhi = new ArrayList<>();
        zhi.add(new Todo("{a}", false));
        zhi.add(new Todo("{b}", false));
        zhi.add(new Todo("{c}", false));
        String line = "done 2";
        int k = Integer.parseInt(line.substring(5));
        zhi.get(k - 1).markDone();
        System.out.println("办完了：" + zhi.get(k - 1).getWhat());
        System.out.println("三条现在这样：" + zhi.get(0) + " / " + zhi.get(1) + " / " + zhi.get(2));
    }
}
